import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
const scene=new THREE.Scene();scene.fog=new THREE.Fog(0x9ca8a4,45,250);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,500);
scene.add(new THREE.HemisphereLight(0xdce9ef,0x29302c,2.25));
const sun=new THREE.DirectionalLight(0xffe6c1,3.2);sun.position.set(-20,30,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
const fill=new THREE.DirectionalLight(0x77b9d1,1.2);fill.position.set(12,9,-20);scene.add(fill);
const ground=new THREE.Mesh(new THREE.PlaneGeometry(200,600),new THREE.MeshStandardMaterial({color:0x28332e,roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.set(0,-.17,-220);ground.receiveShadow=true;scene.add(ground);
const road=new THREE.Mesh(new THREE.PlaneGeometry(13,600),new THREE.MeshStandardMaterial({color:0x252a2d,roughness:.88}));road.rotation.x=-Math.PI/2;road.position.set(0,-.1,-220);road.receiveShadow=true;scene.add(road);
const shoulderMat=new THREE.MeshStandardMaterial({color:0xb6a98a,roughness:1});
for(const x of [-7.2,7.2]){const shoulder=new THREE.Mesh(new THREE.BoxGeometry(.8,.08,600),shoulderMat);shoulder.position.set(x,-.1,-220);scene.add(shoulder)}
const dashMat=new THREE.MeshStandardMaterial({color:0xf2e5bf,emissive:0x332b15,roughness:.7});
for(let lane of [-2.15,2.15])for(let i=0;i<32;i++){const dash=new THREE.Mesh(new THREE.BoxGeometry(.11,.035,3.1),dashMat);dash.position.set(lane,-.055,15-i*18);dash.userData.recycle=true;scene.add(dash)}
const roadSide=new THREE.Group();scene.add(roadSide);
let biome='city';const scenery=[];const traffic=[];let playerCar;let policeCars=[];let playerX=0;let distance=0;let speed=0;let raceRunning=false;let racePaused=false;let selectedLevel=1;let boost=100;let collisionCooldown=0;let gameClock=0;let lastTime=performance.now();
const input={left:false,right:false,throttle:false,brake:false};
const colors={city:{sky:0x8caaa9,fog:0x9ca8a4,ground:0x34433d},forest:{sky:0x9fb8a4,fog:0xa5b5a2,ground:0x34513a},mountain:{sky:0x9eb1bf,fog:0xaab4b8,ground:0x535953},night:{sky:0x111c36,fog:0x26334c,ground:0x171b27},port:{sky:0x8faab3,fog:0x9eafb0,ground:0x39464a}};
const rand=(a,b)=>a+Math.random()*(b-a);
function makeCar(color=0xe53c2f,scale=1,police=false){const group=new THREE.Group();const paint=new THREE.MeshStandardMaterial({color,metalness:.65,roughness:.25});const dark=new THREE.MeshStandardMaterial({color:0x11171a,metalness:.2,roughness:.72});const glass=new THREE.MeshStandardMaterial({color:0x19303b,metalness:.45,roughness:.2});const tire=new THREE.MeshStandardMaterial({color:0x101214,roughness:.9});const glow=new THREE.MeshStandardMaterial({color:police?0x101010:0xf5f2e7,emissive:police?0x000000:0x302a1c});
const body=new THREE.Mesh(new THREE.BoxGeometry(1.9,.55,3.7),paint);body.position.y=.62;body.castShadow=true;group.add(body);const hood=new THREE.Mesh(new THREE.BoxGeometry(1.72,.23,1.05),paint);hood.position.set(0,.84,-1.03);group.add(hood);const cabin=new THREE.Mesh(new THREE.BoxGeometry(1.5,.57,1.62),glass);cabin.position.set(0,1.08,.12);cabin.castShadow=true;group.add(cabin);const roof=new THREE.Mesh(new THREE.BoxGeometry(1.42,.12,1.25),paint);roof.position.set(0,1.4,.15);group.add(roof);
for(let x of [-.97,.97])for(let z of [-1.12,1.15]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.39,.39,.25,16),tire);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.39,z);wheel.castShadow=true;group.add(wheel);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.19,.19,.27,12),new THREE.MeshStandardMaterial({color:0x9da7a9,metalness:.8,roughness:.3}));hub.rotation.z=Math.PI/2;hub.position.set(x,.39,z);group.add(hub)}
for(let x of [-.62,.62]){const lamp=new THREE.Mesh(new THREE.BoxGeometry(.4,.14,.08),glow);lamp.position.set(x,.72,-1.89);group.add(lamp);const tail=new THREE.Mesh(new THREE.BoxGeometry(.4,.13,.06),new THREE.MeshStandardMaterial({color:0xff3030,emissive:0x9c0808}));tail.position.set(x,.72,1.89);group.add(tail)}
if(police){const bar=new THREE.Mesh(new THREE.BoxGeometry(.86,.12,.25),new THREE.MeshStandardMaterial({color:0x111,emissive:0x222222}));bar.position.set(0,1.48,.13);group.add(bar);for(let x of [-.27,.27]){const l=new THREE.Mesh(new THREE.BoxGeometry(.22,.12,.23),new THREE.MeshBasicMaterial({color:x<0?0x2277ff:0xff2525}));l.position.set(x,1.5,.13);group.add(l)}}
group.scale.setScalar(scale);return group;}
playerCar=makeCar(0xe74136,1,false);playerCar.position.set(0,0,3);scene.add(playerCar);
function clearScenery(){for(const o of scenery)scene.remove(o);scenery.length=0;for(const o of traffic)scene.remove(o);traffic.length=0;for(const o of policeCars)scene.remove(o);policeCars.length=0}
function addBuilding(x,z){const h=rand(7,22),w=rand(4,9),d=rand(5,12);const mats=[0x627779,0x8e8a7b,0x526266,0x9a8b77,0x42545a];const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshStandardMaterial({color:mats[Math.floor(rand(0,mats.length))],roughness:.84}));m.position.set(x,h/2-.15,z);m.castShadow=true;scene.add(m);scenery.push(m);if(Math.random()>.3){for(let y=1.7;y<h-1;y+=2.2){const win=new THREE.Mesh(new THREE.BoxGeometry(.1,.75,w*.58),new THREE.MeshStandardMaterial({color:biome==='night'?0xeac96c:0x9db5b7,emissive:biome==='night'?0x74531d:0x080d0e,roughness:.6}));win.position.set(x+(x<0?w/2+.03:-w/2-.03),y,z);scene.add(win);scenery.push(win)}}}
function addTree(x,z){const height=rand(5,11), trunk=new THREE.Mesh(new THREE.CylinderGeometry(.2,.35,height*.43,7),new THREE.MeshStandardMaterial({color:biome==='forest'?0x503b28:0x5c4632}));trunk.position.set(x,height*.22-.15,z);scene.add(trunk);scenery.push(trunk);const crown=new THREE.Mesh(new THREE.ConeGeometry(rand(1.6,2.8),height*.75,7),new THREE.MeshStandardMaterial({color:biome==='forest'?[0x2d5535,0x416541,0x385c40][Math.floor(rand(0,3))]:0x31503a,roughness:1}));crown.position.set(x,height*.7,z);crown.castShadow=true;scene.add(crown);scenery.push(crown)}
function addMountain(x,z){const mesh=new THREE.Mesh(new THREE.ConeGeometry(rand(12,24),rand(35,65),7),new THREE.MeshStandardMaterial({color:[0x65746f,0x778178,0x697880][Math.floor(rand(0,3))],roughness:1}));mesh.position.set(x,rand(10,22),z);mesh.scale.z=rand(.6,1.2);scene.add(mesh);scenery.push(mesh)}
function addPort(x,z){const container=new THREE.Mesh(new THREE.BoxGeometry(rand(4,8),rand(2,3.2),rand(5,9)),new THREE.MeshStandardMaterial({color:[0x345c65,0xa85539,0x3e4d61,0xb38b42][Math.floor(rand(0,4))],roughness:.8}));container.position.set(x,container.geometry.parameters.height/2-.15,z);scene.add(container);scenery.push(container);if(Math.random()>.55){const pole=new THREE.Mesh(new THREE.BoxGeometry(.35,15,.35),new THREE.MeshStandardMaterial({color:0x4c5556,metalness:.6}));pole.position.set(x*1.35,7.4,z);scene.add(pole);scenery.push(pole);const boom=new THREE.Mesh(new THREE.BoxGeometry(10,.3,.3),pole.material);boom.position.set(x*1.35+4,14.4,z);scene.add(boom);scenery.push(boom)}}
function addStreetLamp(x,z){const pole=new THREE.Mesh(new THREE.CylinderGeometry(.055,.08,6,6),new THREE.MeshStandardMaterial({color:0x333e40,metalness:.7}));pole.position.set(x,2.85,z);scene.add(pole);scenery.push(pole);const arm=new THREE.Mesh(new THREE.BoxGeometry(1.7,.07,.07),pole.material);arm.position.set(x+(x<0?.7:-.7),5.7,z);scene.add(arm);scenery.push(arm);const bulb=new THREE.PointLight(0xffd385,biome==='night'?3:.35,17);bulb.position.set(x+(x<0?.9:-.9),5.5,z);scene.add(bulb);scenery.push(bulb)}
function buildEnvironment(){clearScenery();const config=colors[biome];scene.background=new THREE.Color(config.sky);scene.fog.color.setHex(config.fog);ground.material.color.setHex(config.ground);road.material.color.setHex(biome==='night'?0x171a20:biome==='port'?0x333a3c:0x282b2c);sun.intensity=biome==='night'?.45:3.2;fill.intensity=biome==='night'?1.5:1.2;
for(let i=0;i<74;i++){const z=-rand(5,360);if(biome==='city'||biome==='night'){addBuilding(-rand(14,32),z);addBuilding(rand(14,32),z-rand(0,10));if(i%3===0){addStreetLamp(i%2?-8:8,z)}}else if(biome==='forest'){addTree(-rand(10,35),z);addTree(rand(10,35),z-rand(0,8));}else if(biome==='mountain'){addMountain(-rand(18,50),z);addMountain(rand(18,50),z-rand(0,15));if(i%5===0){const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(rand(1,3)),new THREE.MeshStandardMaterial({color:0x626963,roughness:1}));rock.position.set(i%2?-8:8,1,-rand(5,350));scene.add(rock);scenery.push(rock)}}else{addPort(-rand(12,25),z);addPort(rand(12,25),z-rand(0,10));if(i%5===0)addStreetLamp(i%2?-8:8,z)}}
}
function makeTraffic(){for(let i=0;i<7;i++){const car=makeCar([0x4d98a1,0xcac8b9,0x4b5360,0xbd6c3e][i%4],.85);car.position.set([-4.4,-1.45,1.5,4.2][i%4],0,-rand(40,290));car.userData={speed:rand(.45,.88),passed:false};scene.add(car);traffic.push(car)}}
function makePolice(){if(selectedLevel<4)return;for(let i=0;i<(selectedLevel===35?0:Math.min(3,Math.floor((selectedLevel-2)/7)+1));i++){const car=makeCar(0x101820,.88,true);car.position.set(i%2?3.5:-3.5,0,12+i*7);car.userData.phase=Math.random()*10;scene.add(car);policeCars.push(car)}}
function carForSelection(){const d=garageCars[currentCar];playerCar.traverse(o=>{if(o.isMesh&&o.material&&o.material.color&&o.geometry?.type==='BoxGeometry'&&o.geometry.parameters.height===.55)o.material.color.setHex(d.color)});}
// All thirty-five story runs, grouped by the requested locations.
const chapters=[{name:'CITY RUNS',biome:'city',start:1,end:5},{name:'FOREST ROUTE',biome:'forest',start:6,end:10},{name:'MOUNTAIN PASS',biome:'mountain',start:11,end:15},{name:'HIGH COUNTRY',biome:'mountain',start:16,end:20},{name:'SUMMIT SERIES',biome:'mountain',start:21,end:25},{name:'AFTER DARK',biome:'night',start:26,end:30},{name:'THE PORT',biome:'port',start:31,end:35}];
const challengeNames=['Night Shift','Street Sweep','Close Call','No Brakes','Hot Pursuit','Forest Run','Wrong Turn','Deep Cover','Checkpoint Rush','Getaway Driver','Switchback','Cliffhanger','Mountain Drift','High Stakes','Thin Air','Summit Sprint','Blind Corner','Rockslide','No Escape','Peak Performance','Final Ascent','Ridge Runner','Full Throttle','Last Climb','King of the Hill','After Hours','Neon Run','Ghost Route','Heat Check','Midnight Run','Dockside Dash','Cargo Rush','Harbor Heat','Last Shipment','Final Showdown'];
const challengeTypes=['SPRINT','TRAFFIC DODGE','TIME TRIAL','DRIFT RUN','POLICE CHASE'];
const levels=Array.from({length:35},(_,i)=>({id:i+1,name:challengeNames[i],chapter:chapters.find(c=>i+1>=c.start&&i+1<=c.end),type:i===34?'RIVAL DUEL':challengeTypes[i%5],police:i>=2&&i!==34,distance:i===34?4.8:3.2+(i%3)*.55,reward:300+Math.floor(i/5)*125,desc:i===34?'One lane. One rival. This is the run that makes a legend.':`${['Push through the traffic','Keep the line clean','Beat the clock'][i%3]} in the ${chapters.find(c=>i+1>=c.start&&i+1<=c.end).biome}.` }));
const garageCars=[{name:'VORTEX GT',desc:'Lightweight street machine. Built to own the corners.',color:0xe74136,cost:0,speed:57,handling:70,boost:55},{name:'NOVA RS',desc:'A precise, punchy coupe for technical routes.',color:0x26a6a1,cost:1800,speed:68,handling:76,boost:62},{name:'TITAN X',desc:'Heavy power and a relentless top end.',color:0xe0aa32,cost:4200,speed:84,handling:59,boost:73},{name:'PHANTOM R',desc:'Track-bred precision. The ultimate street weapon.',color:0x9d72d1,cost:8500,speed:91,handling:88,boost:86}];
let currentCar=0;let credits=Number(localStorage.getItem('apexCredits')||2450);let unlocked=Number(localStorage.getItem('apexUnlocked')||1);let upgrades=JSON.parse(localStorage.getItem('apexUpgrades')||'{"engine":0,"tires":0,"nitro":0}');let owned=JSON.parse(localStorage.getItem('apexOwned')||'[true,false,false,false]');let activeScreen='home';
const byId=id=>document.getElementById(id);const screens=[...document.querySelectorAll('.screen')];
function showScreen(name){activeScreen=name;screens.forEach(s=>s.classList.toggle('active',s.id===`${name}-screen`));byId('race-screen').classList.toggle('active',name==='race');byId('sound-toggle').style.display=name==='race'?'none':'';if(name==='levels')renderLevels();if(name==='garage')renderGarage();}
function renderLevels(){byId('cash-level').textContent=credits.toLocaleString();const tabRoot=byId('chapter-tabs');tabRoot.innerHTML='';chapters.forEach((c,i)=>{const b=document.createElement('button');b.className=`chapter-tab${i===activeChapter?' active':''}`;b.textContent=c.name;b.onclick=()=>{activeChapter=i;renderLevels()};tabRoot.append(b)});const chapter=chapters[activeChapter];const grid=byId('level-grid');grid.innerHTML='';levels.filter(l=>l.chapter===chapter).forEach(l=>{const b=document.createElement('button');b.className=`level-tile${l.id===selectedLevel?' active':''}${l.id>unlocked?' locked':''}`;b.innerHTML=`${String(l.id).padStart(2,'0')}<span>${l.id<=unlocked?'RUN':'LOCKED'}</span>`;b.onclick=()=>{if(l.id>unlocked){toast('COMPLETE THE PREVIOUS RUN TO UNLOCK');return}selectedLevel=l.id;renderLevels()};grid.append(b)});const l=levels[selectedLevel-1];byId('level-detail').innerHTML=`<div class="detail-kicker">RUN ${String(l.id).padStart(2,'0')} · ${l.chapter.name}</div><h3>${l.name}</h3><div class="detail-tags"><span>${l.type}</span><span>${l.police?'POLICE HEAT':'NO PURSUIT'}</span></div><p>${l.desc}</p><p>Distance <b>${l.distance.toFixed(1)} km</b> &nbsp;·&nbsp; Reward <b>◈ ${l.reward}</b></p><button id="start-run" class="button button-primary compact">START RUN <span>↗</span></button>`;byId('start-run').onclick=()=>startRace()}
let activeChapter=0;
function renderGarage(){byId('cash-garage').textContent=credits.toLocaleString();const car=garageCars[currentCar];byId('car-index').textContent=`${String(currentCar+1).padStart(2,'0')} / 04`;byId('car-name').textContent=car.name;byId('car-desc').textContent=car.desc;const stats=[['SPEED',car.speed+upgrades.engine*3],['HANDLING',car.handling+upgrades.tires*3],['NITRO',car.boost+upgrades.nitro*4]];byId('car-stats').innerHTML=stats.map(([n,v])=>`<div class="stat-row"><span>${n}</span><div class="stat-meter"><i style="width:${Math.min(100,v)}%"></i></div><b>${Math.min(99,v)}</b></div>`).join('');const select=byId('car-buy');select.textContent=owned[currentCar]?(currentCar===0?'SELECT CAR':'SELECT CAR'):`BUY · ◈ ${car.cost.toLocaleString()}`;select.onclick=()=>{if(owned[currentCar]){playerCar.materialColor=car.color;carForSelection();toast(`${car.name} SELECTED`)}else if(credits>=car.cost){credits-=car.cost;owned[currentCar]=true;localStorage.setItem('apexOwned',JSON.stringify(owned));saveState();renderGarage();toast(`${car.name} PURCHASED`)}else toast('NOT ENOUGH CREDITS');};const upgradeNames=[['engine','ENGINE','More top speed','⌁'],['tires','GRIP','Sharper steering','◉'],['nitro','NITRO','Longer boost','ϟ']];byId('upgrade-list').innerHTML=upgradeNames.map(([key,name,desc,icon])=>{const price=650+upgrades[key]*550;return `<div class="upgrade-item"><div class="upgrade-icon">${icon}</div><div><b>${name} · LV ${upgrades[key]}</b><small>${desc}</small></div><button data-upgrade="${key}" ${upgrades[key]>=5?'disabled':''}>◈ ${price}</button></div>`}).join('');document.querySelectorAll('[data-upgrade]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.upgrade,price=650+upgrades[key]*550;if(credits<price){toast('NOT ENOUGH CREDITS');return}if(upgrades[key]>=5)return;credits-=price;upgrades[key]++;saveState();renderGarage();toast(`${key.toUpperCase()} UPGRADED`)})}
function saveState(){localStorage.setItem('apexCredits',credits);localStorage.setItem('apexUnlocked',unlocked);localStorage.setItem('apexUpgrades',JSON.stringify(upgrades));localStorage.setItem('apexOwned',JSON.stringify(owned))}
function startRace(){const level=levels[selectedLevel-1];biome=level.chapter.biome;buildEnvironment();makeTraffic();makePolice();distance=0;speed=0;playerX=0;boost=100;collisionCooldown=0;playerCar.position.set(0,0,3);playerCar.rotation.set(0,0,0);raceRunning=true;racePaused=false;byId('race-stage').textContent=`${biome.toUpperCase()} · RUN ${String(level.id).padStart(2,'0')}`;byId('race-title').textContent=level.name;byId('objective-text').textContent=level.id===35?'BEAT THE RIVAL':level.police?'LOSE THE COPS':'HIT THE FINISH';byId('race-condition').textContent=biome==='night'?'WET NEON ASPHALT':biome==='mountain'?'MOUNTAIN ASPHALT':biome==='forest'?'FOREST ROAD':'DRY ASPHALT';byId('police-status').textContent=level.id===35?'RIVAL IN SIGHT':level.police?'PURSUIT ACTIVE':'NO PURSUIT';byId('progress-fill').style.width='0%';byId('progress-km').textContent=`0.0 / ${level.distance.toFixed(1)} KM`;byId('boost-fill').style.width='100%';byId('pause-overlay').classList.remove('open');byId('result-overlay').classList.remove('open');showScreen('race');soundEngine(true)}
function finishRace(win){raceRunning=false;speed=0;soundEngine(false);const l=levels[selectedLevel-1];const reward=win?l.reward:Math.floor(l.reward*.15);credits+=reward;if(win)unlocked=Math.max(unlocked,Math.min(35,selectedLevel+1));saveState();byId('result-kicker').textContent=win?(selectedLevel===35?'RIVAL DEFEATED':'RUN COMPLETE'):'RUN FAILED';byId('result-title').innerHTML=win?(selectedLevel===35?'YOU OWN THE <em>STREETS.</em>':'CLEAN <em>GETAWAY.</em>'):'TOO <em>SLOW.</em>';byId('result-copy').textContent=win?(selectedLevel===35?'The city has a new legend.':'You left them in the dust.'):'The road is still waiting. Give it another go.';byId('reward-value').textContent=`+${reward.toLocaleString()}`;byId('result-button').textContent=selectedLevel===35&&win?'BACK TO GARAGE':'CONTINUE  ↗';byId('result-button').onclick=()=>{byId('result-overlay').classList.remove('open');if(win&&selectedLevel<35)selectedLevel++;showScreen('levels');};byId('result-overlay').classList.add('open')}
function toast(msg){const t=byId('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),1900)}
// Simple synthesized engine and impact sounds; settings remain usable without audio assets.
let audioCtx=null,engineOsc=null,engineGain=null;function soundEngine(on){if(!audioCtx){try{audioCtx=new (window.AudioContext||window.webkitAudioContext)()}catch{return}}if(on){audioCtx.resume();if(!engineOsc){engineOsc=audioCtx.createOscillator();engineGain=audioCtx.createGain();engineOsc.type='sawtooth';engineGain.gain.value=0;engineOsc.connect(engineGain).connect(audioCtx.destination);engineOsc.start()}engineGain.gain.setTargetAtTime(0.035,audioCtx.currentTime,.25)}else if(engineGain)engineGain.gain.setTargetAtTime(0,audioCtx.currentTime,.2)}function impactSound(){if(!audioCtx||!settings.sfx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='triangle';o.frequency.setValueAtTime(170,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(55,audioCtx.currentTime+.14);g.gain.setValueAtTime(.12,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.16);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.17)}
let settings={music:true,sfx:true,vibration:true};
function gameLoop(now){requestAnimationFrame(gameLoop);const dt=Math.min(.04,(now-lastTime)/1000||0);lastTime=now;gameClock+=dt;const running=raceRunning&&!racePaused;const maxSpeed=(garageCars[currentCar].speed+upgrades.engine*3)/99*68+80;const target=running?(input.throttle?maxSpeed:input.brake?10:Math.max(35,speed-23)):0;speed+=(target-speed)*Math.min(1,dt*(input.brake?3.8:1.15));if(running){const steer=(input.left?-1:0)+(input.right?1:0);playerX+=steer*dt*(1.9+speed/95)*(1+upgrades.tires*.045);playerX=THREE.MathUtils.clamp(playerX,-5.2,5.2);playerCar.position.x+=(playerX-playerCar.position.x)*Math.min(1,dt*8);playerCar.rotation.z=THREE.MathUtils.lerp(playerCar.rotation.z,-steer*.085,dt*5);playerCar.rotation.y=THREE.MathUtils.lerp(playerCar.rotation.y,-steer*.09,dt*4);let worldMove=speed*dt*.2;distance+=speed*dt/3600;for(const obj of scene.children){if(obj.userData.recycle){obj.position.z+=worldMove;if(obj.position.z>20)obj.position.z-=576}}for(const o of scenery){o.position.z+=worldMove;if(o.position.z>25)o.position.z-=rand(280,370)}for(const car of traffic){car.position.z+=worldMove*car.userData.speed;if(car.position.z>15){car.position.z=-rand(200,350);car.position.x=[-4.4,-1.45,1.5,4.2][Math.floor(rand(0,4))];car.userData.passed=false}if(Math.abs(car.position.z-playerCar.position.z)<2.7&&Math.abs(car.position.x-playerX)<1.9&&collisionCooldown<=0){speed*=.47;collisionCooldown=1.1;impactSound();if(settings.vibration&&navigator.vibrate)navigator.vibrate(70);toast('TRAFFIC HIT · SPEED LOST')}if(car.position.z>playerCar.position.z+4&&!car.userData.passed){car.userData.passed=true;boost=Math.min(100,boost+7)}}collisionCooldown-=dt;
