@media*{box-sizing:border-box} :root{--acid:#d5ff3f;--white:#f5f4ed;--muted:#a6aeb2;--ink:#071017;--panel:rgba(9,18,24,.92);--line:rgba(255,255,255,.16)} html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#071017;color:var(--white);font-family:'DM Sans',sans-serif;touch-action:none} #game-shell{position:relative;width:100%;height:100%;min-height:320px;overflow:hidden;background:#101b21}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(4,11,15,.80),transparent 59%),linear-gradient(0deg,rgba(4,10,14,.62),transparent 40%),radial-gradient(ellipse at center,transparent 30%,rgba(0,0,0,.24) 100%);z-index:1}.top-brand{position:absolute;z-index:8;left:4.5%;top:5%;display:flex;align-items:center;gap:10px;font:800 17px 'Barlow Condensed',sans-serif;letter-spacing:2px;pointer-events:none}.brand-mark{display:grid;place-items:center;width:27px;height:27px;background:var(--acid);color:#101714;font:900 italic 19px 'Barlow Condensed';clip-path:polygon(0 0,100% 0,80% 100%,0 100%)}.brand-light{font-weight:500;color:#bbc1bd}.sound-toggle{position:absolute;z-index:8;right:4.5%;top:5%;background:rgba(5,12,16,.34);border:1px solid var(--line);border-radius:3px;color:#e5ebe8;padding:9px 13px;font-size:12px;letter-spacing:1px}.sound-toggle span{font-size:9px;margin-left:5px;color:#d4dad6}.screen{position:absolute;inset:0;z-index:4;display:none}.screen.active{display:block}.home-copy{position:absolute;left:10%;top:21%;max-width:470px}.eyebrow{font-size:10px;letter-spacing:2.5px;font-weight:700;color:#c3cac5;margin:0 0 15px}.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--acid);margin-right:9px;box-shadow:0 0 12px var(--acid)}h1,h2,h3{font-family:'Barlow Condensed',sans-serif;text-transform:uppercase;margin:0;line-height:.86;letter-spacing:.4px}h1{font-size:clamp(72px,11vw,142px);font-weight:900;letter-spacing:-2px;text-shado