arent;padding:9px 13px;white-space:nowrap;font:700 10px 'DM Sans';letter-spacing:1px;cursor:pointer}.chapter-tab.active{border-color:var(--acid);color:var(--acid);background:rgba(213,255,63,.07)}.level-layout{display:grid;grid-template-columns:minmax(300px,1.35fr) minmax(200px,.8fr);gap:25px;align-items:stretch}.level-grid{display:grid;grid-template-columns:repeat(7,minmax(38px,1fr));gap:7px;align-content:start}.level-tile{min-height:47px;border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.035);color:#cbd0cc;font:700 15px 'Barlow Condensed';cursor:pointer;position:relative}.level-tile span{display:block;font:7px 'DM Sans';color:#808b8e;margin-top:3px}.level-tile.active{border-color:var(--acid);background:rgba(213,255,63,.14);color:var(--acid)}.level-tile.locked{opacity:.35;cursor:not-allowed}.level-detail{border-left:1px solid var(--line);padding:6px 0 0 22px;min-height:185px}.level-detail .detail-kicker{font-size:9px;letter-spacing:2px;color:var(--acid);margin-bottom:8px}.le
